#include "usermodfx.h"
#include <stdint.h>
namespace{static constexpr float SR=48000.f;static float zL[3][4]={},zR[3][4]={},ph=0,rt=.25f,dt=.5f,r=.25f,d=.5f;static inline float c01(float x){return x<0?0:(x>1?1:x);}static inline float ca(float x){return x<-1?-1:(x>1?1:x);}static inline float wr(float x){while(x>=1)x-=1;return x;}static inline float ap(float x,float &z,float a){float y=-a*x+z;z=x+a*y;return y;}static void reset(){for(int j=0;j<3;j++)for(int k=0;k<4;k++)zL[j][k]=zR[j][k]=0;ph=0;}}
void MODFX_INIT(uint32_t p,uint32_t a){(void)p;(void)a;reset();}void MODFX_PROCESS(const float*x,float*y,const float*sx,float*sy,uint32_t n){(void)sx;(void)sy;for(uint32_t i=0;i<n;i++){r+=(rt-r)*.0015f;d+=(dt-d)*.0015f;ph=wr(ph+(.015f+.65f*r*r)/SR);float shape=d*(2.f-d);float sumL=0,sumR=0,ws=0;for(int j=0;j<3;j++){float p=wr(ph+j/3.f);float w=fx_sinf(.5f*p);w*=w;float a=.06f+(.84f*shape)*p;float l=x[2*i],rr=x[2*i+1];for(int k=0;k<4;k++){l=ap(l,zL[j][k],a);rr=ap(rr,zR[j][k],.06f+(.84f*shape)*wr(p+.035f));}sumL+=l*w;sumR+=rr*w;ws+=w;}if(ws<.1f)ws=.1f;sumL/=ws;sumR/=ws;float wet=.15f+.85f*shape;y[2*i]=ca(x[2*i]*(1-wet)+sumL*wet);y[2*i+1]=ca(x[2*i+1]*(1-wet)+sumR*wet);}}
void MODFX_SUSPEND(){reset();}void MODFX_RESUME(){reset();}void MODFX_PARAM(uint8_t i,int32_t v){float n=c01(q31_to_f32(v));if(i==k_user_modfx_param_time)rt=n;else if(i==k_user_modfx_param_depth)dt=n;}
